export const ScheduledReportSchema = z.object({
  id: z.string().cuid(),
  farmId: z.string(),
  reportType: z.string(),
  frequency: z.string(),
  recipients: z.string().array(),
  isActive: z.boolean(),
  lastSent: z.coerce.date().nullable(),
  nextSend: z.coerce.date().nullable(),
  createdAt: z.coerce.date(),
  updatedAt: z.coerce.date(),
})

export type ScheduledReport = z.infer<typeof ScheduledReportSchema>

